[Form]
public class AVAKBVInquirerOfTheRequest extends FormRun
{
    Args                        frmArgs;
    DataAreaId                  frmDataAreaId;


    KCS_KBVBuildingProjectTable kcs_KBVBuildingProjectTable;
    SalesQuotationTable         salesQuotationTable;

}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    super();

    frmDataAreaId                       = CompanyInfo::find().DataArea; //curExt();
}

/// <summary>
/// designed From AVA
/// </summary>
public void init()
{
    Common                  locCommon;

    Query                   locQuery;
    QueryBuildDataSource    locQbds;


    if(element.args())
    {
        frmArgs = new Args();
        frmArgs = element.args();

        if(frmArgs.record())
        {
            locCommon = frmArgs.record();

            switch(locCommon.TableId)
            {
                case Tablenum(KCS_KBVBuildingProjectTable):
                    kcs_KBVBuildingProjectTable = locCommon;
                    break;

                case Tablenum(SalesQuotationTable):
                    salesQuotationTable = locCommon;
                    break;


            }
        }
    }

    super();

    locQuery = this.query();

    switch (frmArgs.menuitemName())
    {
        case menuItemDisplayStr(AVAKBVInquirerOfTheRequest):

            if (kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectID)
            {
                locQbds = this.queryBuildDataSource();
                locQbds.clearDynalinks();
                locQbds.addDynalink(fieldNum(KCS_KBVInquirerOfTheRequest, KCS_KBVBuildingProjectID),
                                    kcs_KBVBuildingProjectTable,
                                    fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID));
                /*
                locQbds = this.queryBuildDataSource();
                SysQuery::findOrCreateRange(locQbds, fieldNum(KCS_KBVInquirerOfTheRequest, KCS_KBVBuildingProjectID)).value(queryValue(kcs_KBVBuildingProjectTable.KCS_KBVParentBuildingProjectID));

                locQbds.clearRanges();
                locQuery.dataSourceTable(tableNum(KCS_KBVInquirerOfTheRequest)).clearRange(fieldNum (KCS_KBVInquirerOfTheRequest, KCS_KBVBuildingProjectID));
                locQbr      = locQuery.dataSourceTable(tableNum(KCS_KBVInquirerOfTheRequest)).addRange(fieldNum (KCS_KBVInquirerOfTheRequest, KCS_KBVBuildingProjectID));
                locQbr.value(queryValue(kcs_KBVBuildingProjectTable.KCS_KBVParentBuildingProjectID));
                */
            }
            else if (salesQuotationTable.QuotationId)
            {
                locQbds = this.queryBuildDataSource();
                locQbds.clearDynalinks();
                locQbds.addDynalink(fieldNum(KCS_KBVInquirerOfTheRequest, KCS_KBVRequestID),
                                    salesQuotationTable,
                                    fieldNum(SalesQuotationTable, KCS_KBVRequestID));

                //this.formRun().design().controlName(formControlStr(AVAKBVInquirerOfTheRequest, Grid_KCS_KBVBuildingProjectID)).enabled(false);
                Grid_KCS_KBVBuildingProjectID.enabled(false);
            }
            break;
    }
}

/// <summary>
///    AVA <c>modified</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as type
/// </returns>
public boolean modified()
{
    boolean         ret;
    smmBusRelTable  checkSmmBusRelTable;

    ret = super();

    if(!AVAKBVDirPartyContactPersonHelper::checkContactPersonOnDirPartyId(Grid_DirPartyId.value(), Grid_ContactPersonId.valueStr()))
    {
        Grid_ContactPersonId.text('');
        Grid_editContactPersonName.text('');
    }

    return ret;
}

/// <summary>
///     AVA <c>lookupReference</c> method.
/// </summary>
/// <returns>
///     <c>Common</c> as type
/// </returns>
public Common lookupReference()
{
    Common ret;

    //ret = AVAKBVDirPartyContactPersonHelper::lookupDirPartyBusRel(this, null);
    ret = AVAKBVDirPartyContactPersonHelper::lookupDirPartyCustAndOrOther(this, null, true, true);

    return ret;
}

/// <summary>
///    AVA <c>jumpRef</c> method.
/// </summary>
public void jumpRef()
{
    Grid_ContactPersonId.jumpRef();
}

/// <summary>
///    AVA <c>lookup</c> method.
/// </summary>
void lookup()
{
    ContactPerson::lookupDirContactPerson(  Grid_ContactPersonId,
                                            Grid_DirPartyId.value(),
                                            this,
                                            Grid_ContactPersonId.valueStr()  );
}

/// <summary>
///    AVA <c>modified</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as type
/// </returns>
public boolean modified()
{
    boolean                             ret;

    ContactPersonName                   locContactPersonName;

    AVAKBVDirPartyContactPersonHelper   locAVAKBVDirPartyContactPersonHelper;

    FormDataSource                      locFormDataSource;
    KCS_KBVInquirerOfTheRequest         locKCS_KBVInquirerOfTheRequest;

    ret = super();

    locAVAKBVDirPartyContactPersonHelper = new AVAKBVDirPartyContactPersonHelper();

    locAVAKBVDirPartyContactPersonHelper.parmSet(false);
    locAVAKBVDirPartyContactPersonHelper.parmDataAreaId(frmDataAreaId);
    locAVAKBVDirPartyContactPersonHelper.parmDirPartyId(Grid_DirPartyId.value());
    locAVAKBVDirPartyContactPersonHelper.parmDirPartyName('');
    locAVAKBVDirPartyContactPersonHelper.parmContactPersonId(Grid_ContactPersonId.valueStr());
    locAVAKBVDirPartyContactPersonHelper.parmContactPersonName(Grid_editContactPersonName.valueStr());

    locContactPersonName = locAVAKBVDirPartyContactPersonHelper.getEditContactPersonNameModified();

    Grid_DirPartyId.value(locAVAKBVDirPartyContactPersonHelper.parmDirPartyId());

    locFormDataSource                               = element.KCS_KBVInquirerOfTheRequest_DS;
    locKCS_KBVInquirerOfTheRequest                  = locFormDataSource.cursor();
    locKCS_KBVInquirerOfTheRequest.DirPartyId       = locAVAKBVDirPartyContactPersonHelper.parmDirPartyId();

    locKCS_KBVInquirerOfTheRequest.ContactPersonId  = locAVAKBVDirPartyContactPersonHelper.parmContactPersonId();
    Grid_ContactPersonId.Text(locAVAKBVDirPartyContactPersonHelper.parmContactPersonId());
    Grid_editContactPersonName.text(locAVAKBVDirPartyContactPersonHelper.parmContactPersonName());

    return ret;
}
